'From Squeak6.0 of 8 June 2026 [latest update: #22156] on 26 July 2026 at 11:06:16 pm'!"Change Set:		TTFontReader-onRemote-fixDate:			26 July 2026Author:			Masashi UmezawaFix the TTFontReader >> onRemote: to use a normalised font path name when the platform changes after the image snapshot is taken.  "!!TTFontReader methodsFor: 'initialization' stamp: 'mu 7/26/2026 22:59'!onRemote: aRemoteFontDescription	"Prepare the receiver to operate for aRemoteFontDescription, which means fetching selected glyphs on demand. Avoid storing too much glyph data in the image at once. Only the bare minimum."	self		on: (FileStream readOnlyFileNamed: aRemoteFontDescription normalizedFileName)		offset: aRemoteFontDescription fileOffset.			fontDescription := nil. "Not needed."			numGlyphs := aRemoteFontDescription numGlyphs.	cmapTable := aRemoteFontDescription cmapTable.	numHMetrics := aRemoteFontDescription numHMetrics.	indexToLocFormat := aRemoteFontDescription indexToLocFormat.		tableDictionary := Dictionary new "Ignore length and checksum"		at: 'hmtx' put: { aRemoteFontDescription hmtxTableOffset . nil . nil };		at: 'loca' put: { aRemoteFontDescription indexToLocOffset . nil . nil };		at: 'glyf' put: { aRemoteFontDescription glyphTableOffset . nil . nil };		yourself.! !!TTRemoteFontDescription methodsFor: 'accessing' stamp: 'mu 7/26/2026 22:57'!normalizedFileName	| fName badSeparator tokens |	fName := self fileName.	badSeparator := FileDirectory slash = '\' ifTrue: ['/'] ifFalse: ['\'].	tokens := fName findTokens: badSeparator.	tokens ifNotEmpty: [		fName := tokens joinSeparatedBy: FileDirectory slash	].	^ fName! !